   match('المعنى والكلمة', [('رغبة', 'أريد أن'), ('واجب', 'يجب أن'), ('قدرة', 'أستطيع أن'), ('نفي المستقبل', 'لن'), ('المستقبل القريب', 'سـ')]),
   order('رتّب الجملة', ['أريد', 'أن', 'أصوّرَ', 'النخيل', 'في', 'المزرعة.']),
   order('رتّب الجملة', ['هل', 'يمكن', 'أن', 'تفتحَ', 'المكتبة', 'يوم', 'الخميس؟']),
   order('رتّب الجملة', ['لن', 'أتأخّرَ،', 'وسأحضرُ', 'في', 'السابعة.']),
   pic('«أريد أن أشربَ قهوة» — ماذا تريد سارة؟', ['cup', 'bread', 'book'], 0),
