   pic('«يجب أن أنامَ مبكّرًا»', ['bed', 'bus', 'cafe'], 0),
   cloze('أكمل بالشكل الصحيح', 'أريد أن ___ إلى المزرعة، ويجب أن ___ مبكّرًا، ولن ___.', ['أذهبَ', 'أستيقظَ', 'أتأخّرَ'], ['ذهبتُ', 'استيقظتُ', 'تأخّرتُ']),
   cloze('أكمل مع أنتِ', 'ماريا، هل تستطيعين أن ___ معنا؟ يجب أن ___ قبل الرابعة.', ['تأتي', 'تعودي'], ['تأتين', 'تعودين', 'عدتِ']),
   cloze('أكمل مع أنتم وهم', 'هل يمكن أن ___ على السكن؟ الأصدقاء يريدون أن ___ معنا.', ['تمرّوا', 'يأتوا'], ['تمرّون', 'يأتون', 'مرّوا']),
